/* DAWAH X — ahmad, অধ্যায় 49 · খণ্ড 49 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][49]=[[9601,9601,"","","‏ ‏وَبِالْإِسْنَادِ ‏ ‏نَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُصَلِّيَ الرَّجُلُ فِي الثَّوْبِ الْوَاحِدِ لَيْسَ عَلَى ‏ ‏عَاتِقِهِ ‏ ‏مِنْهُ شَيْءٌ ‏","","",""],[9602,9602,"","","‏ ‏وَبِالْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقْسِمُ وَرَثَتِي دِينَارًا مَا تَرَكْتُ بَعْدَ نَفَقَةِ نِسَائِي وَمَئُونَةِ عَامِلِي فَإِنَّهُ ‏ ‏صَدَقَةٌ ‏","","",""],[9603,9603,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعَتَيْنِ ‏ ‏النِّبَاذِ ‏ ‏وَاللِّمَاسِ ‏ ‏وَعَنْ لُبْسِ ‏ ‏الصَّمَّاءِ ‏ ‏وَأَنْ ‏ ‏يَحْتَبِيَ ‏ ‏الرَّجُلُ فِي ثَوْبٍ وَاحِدٍ لَيْسَ بَيْنَهُ وَبَيْنَ الْأَرْضِ شَيْءٌ ‏","","",""],[9604,9604,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ فَمَنْ تَرَكَ دَيْنًا أَوْ ضَيَاعًا فَإِلَيَّ وَمَنْ تَرَكَ مَالًا فَلِلْوَارِثِ ‏","","",""],[9605,9605,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنِ ‏ ‏عَمَّارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَاءَ خَادِمُ أَحَدِكُمْ بِطَعَامِهِ قَدْ كَفَاهُ ‏ ‏حَرَّهُ ‏ ‏وَعَمَلَهُ فَلْيُقْعِدْهُ يَأْكُلُ مَعَهُ أَوْ يُنَاوِلْهُ لُقْمَةً ‏","","",""],[9606,9606,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏وَمُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قِيلَ لَهُ أَنْفِقْ أُنْفِقْ عَلَيْكَ ‏ ‏قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏فِي حَدِيثِهِ قَالَ يَقُولُ رَبُّنَا عَزَّ وَجَلَّ ‏ ‏أَنْفِقْ أُنْفِقْ عَلَيْكَ ‏","","",""],[9607,9607,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَصُومُ الْمَرْأَةُ وَزَوْجُهَا حَاضِرٌ إِلَّا بِإِذْنِهِ ‏","","",""],[9608,9608,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏وَمُؤَمَّلٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عُثْمَانَ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏قَالَ ‏ ‏ارْكَبْهَا قَالَ يَا رَسُولَ اللَّهِ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا ‏","","",""],[9609,9609,"","","‏ ‏قَالَ ‏ ‏وَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُبَالَ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏الَّذِي لَا يَجْرِي ثُمَّ يُغْتَسَلَ مِنْهُ ‏ ‏قَالَ ‏ ‏مُؤَمَّلٌ ‏ ‏الرَّاكِدِ ثُمَّ يُغْتَسَلَ مِنْهُ ‏","","",""],[9610,9610,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَمَّارٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَقِيَ ‏ ‏آدَمَ ‏ ‏مُوسَى ‏ ‏فَقَالَ أَنْتَ ‏ ‏آدَمُ ‏ ‏الَّذِي خَلَقَكَ اللَّهُ بِيَدِهِ وَأَسْجَدَ لَكَ مَلَائِكَتَهُ وَأَسْكَنَكَ الْجَنَّةَ ثُمَّ فَعَلْتَ فَقَالَ أَنْتَ ‏ ‏مُوسَى ‏ ‏الَّذِي كَلَّمَكَ اللَّهُ وَاصْطَفَاكَ بِرِسَالَتِهِ وَأَنْزَلَ عَلَيْكَ التَّوْرَاةَ ثُمَّ أَنَا أَقْدَمُ أَمْ الذِّكْرُ قَالَ لَا بَلْ الذِّكْرُ ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏رَجُلٍ قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَظُنُّهُ ‏ ‏جُنْدُبَ بْنَ عَبْدِ اللَّهِ الْبَجَلِيَّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَقِيَ ‏ ‏آدَمَ ‏ ‏مُوسَى ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[9611,9611,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ فَالْمَوْلُودُ قَالَ ‏ ‏اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ‏","","",""],[9612,9612,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَطَاعَ الْعَبْدُ رَبَّهُ وَأَطَاعَ سَيِّدَهُ فَلَهُ أَجْرَانِ ‏","","",""],[9613,9613,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏وَعَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَخْرُجَنَّ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏رِجَالٌ رَغْبَةً عَنْهَا ‏ ‏وَالْمَدِينَةُ ‏ ‏خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏وَمُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[9614,9614,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُجْمَعُ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا وَلَا بَيْنَ الْمَرْأَةِ وَخَالَتِهَا ‏","","",""],[9615,9615,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَلْيَغْسِلْ يَدَهُ قَبْلَ أَنْ يُدْخِلَهَا فِي إِنَائِهِ فَإِنَّ أَحَدَكُمْ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏","","",""],[9616,9616,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ شَرِّ النَّاسِ ذُو الْوَجْهَيْنِ الَّذِي يَأْتِي هَؤُلَاءِ بِوَجْهٍ وَهَؤُلَاءِ بِوَجْهٍ ‏","","",""],[9617,9617,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الصِّيَامَ ‏ ‏جُنَّةٌ ‏ ‏فَإِذَا كَانَ أَحَدُكُمْ صَائِمًا فَلَا ‏ ‏يَرْفُثْ ‏ ‏وَلَا يَجْهَلْ فَإِنْ امْرُؤٌ شَاتَمَهُ أَوْ قَاتَلَهُ فَلْيَقُلْ إِنِّي صَائِمٌ ‏","","",""],[9618,9618,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ عَزَّ وَجَلَّ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏ ‏يَقُولُ إِنَّمَا ‏ ‏يَذَرُ ‏ ‏شَهْوَتَهُ وَطَعَامَهُ وَشَرَابَهُ مِنْ أَجْلِي فَالصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ مِنْ كُلِّ حَسَنَةٍ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِ مِائَةِ ضِعْفٍ إِلَّا الصِّيَامَ فَهُوَ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ ‏","","",""],[9619,9619,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ كَمَثَلِ الصَّائِمِ ‏ ‏الدَّائِمِ ‏ ‏الْقَائِمِ الَّذِي لَا ‏ ‏يَفْتُرُ ‏ ‏مِنْ صِيَامٍ وَصَلَاةٍ حَتَّى يَرْجِعَ ‏","","",""],[9620,9620,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ وَالظَّنَّ فَإِنَّ ‏ ‏الظَّنَّ ‏ ‏أَكْذَبُ الْحَدِيثِ وَلَا ‏ ‏تَجَسَّسُوا ‏ ‏وَلَا ‏ ‏تَحَسَّسُوا ‏ ‏وَلَا تَنَافَسُوا وَلَا تَحَاسَدُوا وَلَا تَبَاغَضُوا وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[9621,9621,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَطْلُ ‏ ‏الْغَنِيِّ ظُلْمٌ وَإِذَا ‏ ‏أُتْبِعَ ‏ ‏أَحَدُكُمْ عَلَى مَلِيءٍ ‏ ‏فَلْيَتْبَعْ ‏","","",""],[9622,9622,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا انْتَعَلَ أَحَدُكُمْ فَلْيَبْدَأْ بِالْيَمِينِ وَإِذَا ‏ ‏نَزَعَ ‏ ‏فَلْيَبْدَأْ بِالشِّمَالِ وَلْتَكُنْ الْيُمْنَى أَوَّلَهُمَا ‏ ‏تُنْعَلُ ‏ ‏وَآخِرَهُمَا ‏ ‏تُنْزَعُ ‏","","",""],[9623,9623,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَلَقَّوْا ‏ ‏الرُّكْبَانَ ‏ ‏وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا يَبِعْ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏وَلَا ‏ ‏تُصَرُّوا ‏ ‏الْإِبِلَ وَالْغَنَمَ فَمَنْ ‏ ‏ابْتَاعَهَا ‏ ‏بَعْدَ ذَلِكَ فَهُوَ بِخَيْرِ ‏ ‏النَّظَرَيْنِ ‏ ‏بَعْدَ أَنْ يَحْلُبَهَا إِنْ رَضِيَهَا أَمْسَكَهَا وَإِنْ سَخِطَهَا رَدَّهَا وَصَاعًا مِنْ تَمْرٍ ‏","","",""],[9624,9624,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتَ الرَّجُلَ يَقُولُ هَلَكَ النَّاسُ فَهُوَ ‏ ‏أَهْلَكُهُمْ ‏","","",""],[9625,9625,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُفْتَحُ أَبْوَابُ السَّمَاءِ يَوْمَ الْاثْنَيْنِ وَيَوْمَ الْخَمِيسِ فَيُغْفَرُ لِكُلِّ عَبْدٍ لَا يُشْرِكُ بِاللَّهِ شَيْئًا إِلَّا رَجُلًا كَانَتْ بَيْنَهُ وَبَيْنَ أَخِيهِ ‏ ‏شَحْنَاءُ ‏ ‏فَيَقُولُ أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا ‏","","",""],[9626,9626,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ عُبَادَةَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنْ وَجَدْتُ مَعَ امْرَأَتِي رَجُلًا أُمْهِلُهُ حَتَّى آتِيَ بِأَرْبَعَةِ شُهَدَاءَ قَالَ نَعَمْ ‏","","",""],[9627,9627,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏خُبَيْبٍ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏خُبَيْبٍ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَوْ ‏ ‏عَنِ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَمِنْبَرِي عَلَى حَوْضِي ‏","","",""],[9628,9628,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلْمَانَ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا خَيْرٌ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏","","",""],[9629,9629,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَدِّدُوا ‏ ‏وَقَارِبُوا ‏ ‏وَاعْلَمُوا أَنَّ أَحَدًا مِنْكُمْ لَيْسَ بِمُنْجِيهِ عَمَلُهُ قَالُوا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ بِرَحْمَتِهِ ‏","","",""],[9630,9630,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَإِسْرَائِيلُ ‏ ‏كِلَاهُمَا ‏ ‏عَنِ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَجُلٌ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مُرْنِي بِأَمْرٍ قَالَ لَا تَغْضَبْ قَالَ فَمَرَّ ‏ ‏أَوْ فَذَهَبَ ‏ ‏ثُمَّ رَجَعَ قَالَ مُرْنِي بِأَمْرٍ قَالَ لَا تَغْضَبْ قَالَ فَرَدَّدَ مِرَارًا كُلُّ ذَلِكَ يَرْجِعُ فَيَقُولُ لَا تَغْضَبْ ‏","","",""],[9631,9631,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُثَنَّى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ كَعْبٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْعَلُوا الطَّرِيقَ سَبْعَ أَذْرُعٍ ‏","","",""],[9632,9632,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَمِسْعَرٍ ‏ ‏عَنِ ‏ ‏إِبْرَاهِيمَ بْنِ عَامِرِ بْنِ مَسْعُودٍ الْجُمَحِيِّ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏وَقَالَ ‏ ‏مِسْعَرٌ ‏ ‏أَظُنُّهُ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَرُّوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ فَأَثْنَوْا عَلَيْهَا خَيْرًا فَقَالَ وَجَبَتْ ثُمَّ مَرُّوا عَلَيْهِ بِجِنَازَةٍ فَأَثْنَوْا عَلَيْهَا شَرًّا فَقَالَ وَجَبَتْ فَقَالُوا يَا رَسُولَ اللَّهِ مَا وَجَبَتْ قَالَ ‏ ‏بَعْضُكُمْ شُهَدَاءُ عَلَى بَعْضٍ ‏","","",""],[9633,9633,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا فَرَغَ اللَّهُ مِنْ الْخَلْقِ كَتَبَ عَلَى عَرْشِهِ رَحْمَتِي سَبَقَتْ غَضَبِي ‏","","",""],[9634,9634,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏","","",""],[9635,9635,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُحِبُّ أَحَدُكُمْ إِذَا رَجَعَ إِلَى ‏ ‏أَهْلِهِ ‏ ‏يَجِدُ ثَلَاثَ ‏ ‏خَلِفَاتٍ ‏ ‏عِظَامٍ سِمَانٍ ‏ ‏فَثَلَاثُ آيَاتٍ يَقْرَأُ بِهِنَّ أَحَدُكُمْ فِي صَلَاتِهِ خَيْرٌ لَهُ مِنْ ثَلَاثِ ‏ ‏خَلِفَاتٍ ‏ ‏عِظَامٍ سِمَانٍ إِنَّ أَثْقَلَ الصَّلَاةِ عَلَى الْمُنَافِقِينَ صَلَاةُ الْعِشَاءِ وَالْفَجْرِ وَلَوْ يَعْلَمُونَ مَا فِيهِمَا لَأَتَوْهُمَا وَلَوْ حَبْوًا ‏","","",""],[9636,9636,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَعْدَدْتُ لِعِبَادِي الصَّالِحِينَ مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ ‏ ‏ذُخْرًا ‏ ‏بَلْهَ مَا أَطْلَعَكُمْ عَلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ إِلَّا أَنَّهُ قَالَ مَا قَدْ أَطْلَعَكُمْ عَلَيْهِ ‏","","",""],[9637,9637,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنِ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏سَجَدَ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏فَقُلْتُ أَلَمْ أَرَكَ سَجَدْتَ فِيهَا قَالَ لَوْ لَمْ أَرَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجَدَ فِيهَا لَمْ أَسْجُدْ ‏","","",""],[9638,9638,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَرْوَانَ الْأَصْفَرِ ‏ ‏وَعَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏أَبَا رَافِعٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَسْجُدُ فِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏قَالَ قُلْتُ تَسْجُدُ فِيهَا قَالَ رَأَيْتُ ‏ ‏خَلِيلِي ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِيهَا فَلَا أَزَالُ أَسْجُدُ فِيهَا حَتَّى أَلْقَاهُ ‏","","",""],[9639,9639,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏الْوَلَدُ ‏ ‏لِرَبِّ ‏ ‏الْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏","","",""],[9640,9640,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خِيَارُكُمْ أَحَاسِنُكُمْ أَخْلَاقًا إِذَا فَقِهُوا ‏","","",""],[9641,9641,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏لَا يَنْظُرُ اللَّهُ عَزَّ وَجَلَّ إِلَى الَّذِي يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏بَطَرًا ‏","","",""],[9642,9642,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏يَقُولُ أَحْسِنُوا الْوُضُوءَ فَإِنِّي سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏","","",""],[9643,9643,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏كُلُّ الْعَمَلِ ‏ ‏كَفَّارَةٌ ‏ ‏إِلَّا الصَّوْمَ وَالصَّوْمُ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ ‏","","",""],[9644,9644,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏","","",""],[9645,9645,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِتَمْرٍ مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏فَأَمَرَ فِيهِ بِأَمْرٍ ثُمَّ حَمَلَ ‏ ‏الْحَسَنَ ‏ ‏أَوْ ‏ ‏الْحُسَيْنَ ‏ ‏عَلَى ‏ ‏عَاتِقِهِ ‏ ‏وَإِذَا لُعَابُهُ يَسِيلُ فَنَظَرَ إِلَيْهِ فَإِذَا هُوَ يَلُوكُ تَمْرَةً مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏قَالَ فَقَالَ أَلْقِهَا أَمَا شَعَرْتَ ‏ ‏أَنَّ آلَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْكُلُونَ ‏ ‏الصَّدَقَةَ ‏","","",""],[9646,9646,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ذَرُونِي ‏ ‏مَا تَرَكْتُكُمْ فَإِنَّمَا هَلَكَ الَّذِينَ مِنْ قَبْلِكُمْ بِسُؤَالِهِمْ وَاخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ فَإِذَا أَمَرْتُكُمْ بِأَمْرٍ فَأْتُوهُ مَا اسْتَطَعْتُمْ وَإِذَا نَهَيْتُكُمْ عَنْ أَمْرٍ فَاجْتَنِبُوهُ ‏","","",""],[9647,9647,"","","‏ ‏و قَالَ ‏ ‏يَعْنِي ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا وَلَكِنْ ‏ ‏سَدِّدُوا ‏ ‏وَقَارِبُوا ‏ ‏وَأَبْشِرُوا ‏","","",""],[9648,9648,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَأَذُودَنَّ ‏ ‏عَنْ حَوْضِي رِجَالًا كَمَا ‏ ‏تُذَادُ ‏ ‏الْغَرِيبَةُ مِنْ الْإِبِلِ ‏","","",""],[9649,9649,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏مَا يَسُرُّنِي أَنَّ لِي ‏ ‏أُحُدًا ‏ ‏ذَهَبًا يَأْتِي عَلَيَّ ثَلَاثٌ وَعِنْدِي مِنْهُ دِينَارٌ لَيْسَ شَيْئًا ‏ ‏أَرْصُدُهُ ‏ ‏لِدَيْنٍ ‏","","",""],[9650,9650,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏نَارُ بَنِي ‏ ‏آدَمَ ‏ ‏الَّتِي يُوقِدُونَ جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنْ نَارِ جَهَنَّمَ فَقَالَ رَجُلٌ إِنْ كَانَتْ لَكَافِيَةً فَقَالَ لَقَدْ فُضِّلَتْ عَلَيْهِ بِتِسْعَةٍ وَسِتِّينَ جُزْءًا حَرًّا فَحَرًّا ‏","","",""],[9651,9651,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَيْنَمَا رَجُلٌ يَمْشِي قَدْ أَعْجَبَتْهُ ‏ ‏جُمَّتُهُ ‏ ‏وَبُرْدَاهُ إِذْ خُسِفَ بِهِ الْأَرْضُ فَهُوَ ‏ ‏يَتَجَلْجَلُ ‏ ‏فِيهَا إِلَى أَنْ تَقُومَ السَّاعَةُ ‏","","",""],[9652,9652,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏دَخَلَتْ امْرَأَةٌ النَّارَ فِي هِرٍّ ‏ ‏أَوْ هِرَّةٍ ‏ ‏رَبَطَتْهَا فَلَمْ تُطْعِمْهَا وَلَمْ تَسْقِهَا وَلَمْ تُرْسِلْهَا تَأْكُلُ مِنْ ‏ ‏خَشَاشِ ‏ ‏الْأَرْضِ ‏","","",""],[9653,9653,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الدَّابَّةُ ‏ ‏الْعَجْمَاءُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏","","",""],[9654,9654,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنِي ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏أَنَّ رَجُلًا قَالَ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏إِنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقْرَأُ فِي يَوْمِ الْجُمُعَةِ بِسُورَةِ ‏ ‏الْجُمُعَةِ ‏ ‏وَ ‏ ‏إِذَا جَاءَكَ الْمُنَافِقُونَ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ بِهِمَا ‏","","",""],[9655,9655,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَلْقَمَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ وَمَنْ أَطَاعَ الْأَمِيرَ فَقَدْ أَطَاعَنِي وَمَنْ عَصَى الْأَمِيرَ فَقَدْ عَصَانِي ‏","","",""],[9656,9656,"","","‏ ‏إِنَّمَا الْإِمَامُ ‏ ‏جُنَّةٌ ‏ ‏فَإِنْ صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ فَإِذَا وَافَقَ قَوْلُ أَهْلِ الْأَرْضِ قَوْلَ أَهْلِ السَّمَاءِ غُفِرَ لَهُ مَا مَضَى مِنْ ذَنْبِهِ ‏","","",""],[9657,9657,"","","‏ ‏قَالَ ‏ ‏وَيَهْلِكُ ‏ ‏قَيْصَرُ ‏ ‏فَلَا ‏ ‏قَيْصَرَ ‏ ‏بَعْدَهُ وَيَهْلِكُ ‏ ‏كِسْرَى ‏ ‏فَلَا ‏ ‏كِسْرَى ‏ ‏بَعْدَهُ ‏","","",""],[9658,9658,"","","‏ ‏قَالَ ‏ ‏وَكَانَ يَتَعَوَّذُ مِنْ خَمْسٍ مِنْ عَذَابِ الْقَبْرِ وَعَذَابِ جَهَنَّمَ ‏ ‏وَفِتْنَةِ ‏ ‏الْمَحْيَا ‏ ‏وَفِتْنَةِ ‏ ‏الْمَمَاتِ ‏ ‏وَفِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏","","",""],[9659,9659,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏فِيمَا أَعْلَمُ شَكَّ ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قُرَيْشٌ ‏ ‏وَالْأَنْصَارُ ‏ ‏وَأَسْلَمُ ‏ ‏وَغِفَارُ ‏ ‏وَجُهَيْنَةُ ‏ ‏وَمُزَيْنَةُ ‏ ‏وَأَشْجَعُ ‏ ‏مَوَالِيَّ ‏ ‏لَيْسَ لَهُمْ ‏ ‏مَوْلًى ‏ ‏دُونَ اللَّهِ وَرَسُولِهِ ‏","","",""],[9660,9660,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏إِنَّهُ سَمِعَ ‏ ‏أَبَا سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ رَكْعَتَيْنِ ثُمَّ سَلَّمَ فَقِيلَ لَهُ نَقَصَ مِنْ الصَّلَاةِ فَصَلَّى رَكْعَتَيْنِ آخَرَتَيْنِ ثُمَّ سَلَّمَ ثُمَّ سَجَدَ سَجْدَتَيْنِ ‏","","",""],[9661,9661,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَسْلَمُ ‏ ‏وَغِفَارُ ‏ ‏وَمُزَيْنَةُ ‏ ‏وَمَنْ كَانَ مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏وَمَنْ كَانَ مِنْ ‏ ‏مُزَيْنَةَ ‏ ‏خَيْرٌ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏وَبَنِي عَامِرٍ ‏ ‏وَالْحَلِيفَيْنِ ‏ ‏أَسَدٍ ‏ ‏وَغَطَفَانَ ‏","","",""],[9662,9662,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمَيْدَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَنْبَغِي لِعَبْدٍ أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏","","",""],[9663,9663,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏وَسَأَلَ ‏ ‏الْأَغَرَّ ‏ ‏عَنْ هَذَا الْحَدِيثِ ‏ ‏فَحَدَّثَ ‏ ‏الْأَغَرُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْكَعْبَةَ ‏","","",""],[9664,9664,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زُرَارَةَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏زُرَارَةَ بْنَ أَوْفَى ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا بَاتَتْ الْمَرْأَةُ ‏ ‏هَاجِرَةً ‏ ‏فِرَاشَ زَوْجِهَا لَعَنَتْهَا الْمَلَائِكَةُ حَتَّى تَرْجِعَ ‏","","",""],[9665,9665,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏هِلاَلاً الْمُزَنِيَّ ‏ ‏أَوْ ‏ ‏الْمَازِنِيَّ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ هَذِهِ ‏ ‏الْحَبَّةُ السَّوْدَاءُ دَوَاءٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ شِفَاءٌ ‏ ‏مِنْ كُلِّ شَيْءٍ إِلَّا ‏ ‏السَّامَ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَالسَّامُ الْمَوْتُ ‏","","",""],[9666,9666,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شُعْبَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَزِيدَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذِهِ ‏ ‏الْحَبَّةَ السَّوْدَاءَ شِفَاءٌ مِنْ كُلِّ دَاءٍ إِلَّا ‏ ‏السَّامَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ ‏ ‏لِقَتَادَةَ ‏ ‏مَا ‏ ‏السَّامُ ‏ ‏قَالَ الْمَوْتُ ‏","","",""],[9667,9667,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النَّضْرَ بْنَ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا أَفْلَسَ الرَّجُلُ فَوَجَدَ مَتَاعَهُ بِعَيْنِهِ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[9668,9668,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَنْبَأَنِي ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏هِلَالَ بْنَ يَزِيدَ ‏ ‏مِنْ ‏ ‏بَنِي مَازِنِ بْنِ شَيْبَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذِهِ ‏ ‏الْحَبَّةَ السَّوْدَاءَ شِفَاءٌ مِنْ كُلِّ شَيْءٍ لَيْسَ ‏ ‏السَّامَ ‏ ‏و قَالَ ‏ ‏قَتَادَةُ ‏ ‏السَّامُ ‏ ‏الْمَوْتُ ‏","","",""],[9669,9669,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنِ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى ‏ ‏جَائِزَةٌ ‏","","",""],[9670,9670,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏فِي الْمَمْلُوكِ بَيْنَ الرَّجُلَيْنِ فَيُعْتِقُ أَحَدُهُمَا نَصِيبَهُ قَالَ ‏ ‏يَضْمَنُ ‏","","",""],[9671,9671,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النَّضْرَ بْنَ أَنَسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ خَاتَمِ الذَّهَبِ ‏","","",""],[9672,9672,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَخْمَ الْكَفَّيْنِ ‏","","",""],[9673,9673,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏سَأَلَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَخْمَ الْكَفَّيْنِ وَالْقَدَمَيْنِ لَمْ أَرَ بَعْدَهُ مِثْلَهُ ‏","","",""],[9674,9674,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ عَلَى غُلَامِ الْمُسْلِمِ وَلَا عَلَى فَرَسِهِ ‏ ‏صَدَقَةٌ ‏","","",""],[9675,9675,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏أَبِي حَصِينٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ذَكْوَانَ أَبَا صَالِحٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي إِنَّ الشَّيْطَانَ لَا ‏ ‏يَتَصَوَّرُ ‏ ‏بِي ‏ ‏أَوْ قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا يَتَشَبَّهُ بِي ‏ ‏وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[9676,9676,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏أَبِي رُهْمٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ أَلَا أَدُلُّكَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏أَوَلَا أَدُلُّكَ ‏ ‏عَلَى ‏ ‏كَنْزٍ ‏ ‏مِنْ كُنُوزِ الْجَنَّةِ لَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[9677,9677,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ كَانَ الْعِلْمُ ‏ ‏بِالثُّرَيَّا ‏ ‏لَتَنَاوَلَهُ نَاسٌ مِنْ أَبْنَاءِ ‏ ‏فَارِسَ ‏","","",""],[9678,9678,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اشْتَرَى شَاةً فَوَجَدَهَا ‏ ‏مُصَرَّاةً ‏ ‏فَهُوَ ‏ ‏بِالْخِيَارِ ‏ ‏فَلْيَرُدَّهَا إِنْ شَاءَ وَيَرُدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ ‏","","",""],[9679,9679,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَيْرُ نِسَاءٍ رَكِبْنَ الْإِبِلَ أَحْنَاهُ عَلَى وَلَدٍ وَأَرْعَاهُ عَلَى زَوْجٍ فِي ذَاتِ يَدِهِ ‏ ‏يَعْنِي نِسَاءَ ‏ ‏قُرَيْشٍ ‏","","",""],[9680,9680,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ ‏","","",""],[9681,9681,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ يُدْخِلُهُ عَمَلُهُ الْجَنَّةَ قَالُوا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ بِرَحْمَةٍ مِنْهُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏وَفَضْلٌ وَوَضَعَ يَدَهُ عَلَى رَأْسِهِ ‏","","",""],[9682,9682,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا تَبَاغَضُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[9683,9683,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ سَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏لَسَلَكْتُ وَادِيَ ‏ ‏الْأَنْصَارِ ‏ ‏أَوْ ‏ ‏شِعْبَهُمْ ‏ ‏وَلَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَمَا ظَلَمَ بِأَبِي وَأُمِّي لَقَدْ آوَوْهُ وَنَصَرُوهُ ‏ ‏أَوْ وَاسَوْهُ وَنَصَرُوهُ ‏","","",""],[9684,9684,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏الْمَعْنَى إِلَّا أَنَّهُ قَالَ سَمِعَ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَغِفَارُ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏","","",""],[9685,9685,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ ‏ ‏فِي الْجَنَّةِ شَجَرَةً يَسِيرُ ‏ ‏الرَّاكِبُ ‏ ‏فِي ظِلِّهَا مِائَةَ عَامٍ لَا يَقْطَعُهَا ‏","","",""],[9686,9686,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَيْرُكُمْ إِسْلَامًا أَحَاسِنُكُمْ أَخْلَاقًا إِذَا فَقِهُوا ‏","","",""],[9687,9687,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيْسَ الْمِسْكِينُ بِالطَّوَّافِ الَّذِي تَرُدُّهُ التَّمْرَةُ وَالتَّمْرَتَانِ وَالْأُكْلَةُ وَالْأُكْلَتَانِ وَلَكِنَّ الْمِسْكِينَ الَّذِي لَا يَجِدُ غِنًى يُغْنِيهِ وَلَا يَسْأَلُ النَّاسَ ‏ ‏إِلْحَافًا ‏","","",""],[9688,9688,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّ ‏ ‏فِي الْجُمُعَةِ لَسَاعَةً لَا ‏ ‏يُوَافِقُهَا ‏ ‏رَجُلٌ مُسْلِمٌ يَسْأَلُ اللَّهَ فِيهَا خَيْرًا إِلَّا أَعْطَاهُ إِيَّاهُ ‏","","",""],[9689,9689,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَمَا ‏ ‏يَخْشَى أَحَدُكُمْ إِذَا رَفَعَ رَأْسَهُ وَالْإِمَامُ سَاجِدٌ أَنْ يَجْعَلَ اللَّهُ تَعَالَى رَأْسَهُ رَأْسَ حِمَارٍ ‏","","",""],[9690,9690,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَعَوَّذُ بِاللَّهِ مِنْ ‏ ‏فِتْنَةِ ‏ ‏الْمَحْيَا وَالْمَمَاتِ وَمِنْ عَذَابِ الْقَبْرِ وَمِنْ شَرِّ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏","","",""],[9691,9691,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنِ ‏ ‏ابْنِ قَارِظٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[9692,9692,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا رَفَعَ رَأْسَهُ مِنْ الرَّكْعَةِ الْأَخِيرَةِ مِنْ صَلَاةِ الْعِشَاءِ الْآخِرَةِ ‏ ‏قَنَتَ ‏ ‏وَقَالَ ‏ ‏اللَّهُمَّ أَنْجِ ‏ ‏الْوَلِيدَ بْنَ الْوَلِيدِ ‏ ‏اللَّهُمَّ أَنْجِ ‏ ‏سَلَمَةَ بْنَ هِشَامٍ ‏ ‏اللَّهُمَّ أَنْجِ ‏ ‏عَيَّاشَ بْنَ أَبِي رَبِيعَةَ ‏ ‏اللَّهُمَّ أَنْجِ الْمُسْتَضْعَفِينَ مِنْ الْمُؤْمِنِينَ اللَّهُمَّ اشْدُدْ ‏ ‏وَطْأَتَكَ ‏ ‏عَلَى ‏ ‏مُضَرَ ‏ ‏اللَّهُمَّ اجْعَلْهَا سِنِينَ ‏ ‏كَسِنِي ‏ ‏يُوسُفَ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[9693,9693,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏لَأُقَرِّبَنَّ ‏ ‏بِكُمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَقْنُتُ ‏ ‏فِي الرَّكْعَةِ الْآخِرَةِ مِنْ صَلَاةِ الظُّهْرِ وَصَلَاةِ الْعِشَاءِ الْآخِرَةِ وَصَلَاةِ الصُّبْحِ بَعْدَمَا يَقُولُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ وَيَدْعُو لِلْمُؤْمِنِينَ وَيَلْعَنُ الْكَافِرِينَ ‏","","",""],[9694,9694,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصْدَقُ كَلِمَةٍ قَالَهَا شَاعِرٌ كَلِمَةُ ‏ ‏لَبِيدٍ ‏ ‏أَلَا كُلُّ شَيْءٍ مَا ‏ ‏خَلَا ‏ ‏اللَّهَ بَاطِلُ ‏ ‏وَكَادَ ‏ ‏أُمَيَّةُ بْنُ أَبِي الصَّلْتِ ‏ ‏أَنْ يُسْلِمَ ‏","","",""],[9695,9695,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ عَلَى الْمُؤْمِنِ فِي عَبْدِهِ وَلَا فِي فَرَسِهِ ‏ ‏صَدَقَةٌ ‏","","",""],[9696,9696,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏إِبْرَاهِيمَ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذُكِرَ عِنْدَهُ رَجُلٌ مَاتَ فَقَالُوا خَيْرًا وَأَثْنَوْا عَلَيْهِ خَيْرًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَبَتْ وَذُكِرَ عِنْدَهُ رَجُلٌ آخَرُ فَقَالُوا شَرًّا وَأَثْنَوْا شَرًّا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَبَتْ قَالَ ‏ ‏أَنْتُمْ شُهَدَاءُ بَعْضُكُمْ عَلَى بَعْضٍ ‏","","",""],[9697,9697,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[9698,9698,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلِيمٌ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِيَّاكُمْ وَالظَّنَّ فَإِنَّ ‏ ‏الظَّنَّ ‏ ‏مِنْ أَكْذَبِ الْحَدِيثِ وَلَا ‏ ‏تَجَسَّسُوا ‏ ‏وَلَا ‏ ‏تَحَسَّسُوا ‏ ‏وَلَا تَبَاغَضُوا وَلَا ‏ ‏تَحَاسَدُوا ‏ ‏وَلَا تَنَافَسُوا وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[9699,9699,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ كُتِبَ لَهُ ‏ ‏قِيرَاطٌ ‏ ‏فَإِنْ تَبِعَهَا حَتَّى ‏ ‏يُقْضَى دَفْنُهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏أَصْغَرُهُمَا ‏ ‏أَوْ أَحَدُهُمَا ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏ ‏فَبَلَغَ ذَلِكَ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَتَعَاظَمَهُ فَأَرْسَلَ إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ صَدَقَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَقَدْ ‏ ‏فَرَّطْنَا ‏ ‏فِي ‏ ‏قَرَارِيطَ ‏ ‏كَثِيرَةٍ ‏","","",""],[9700,9700,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَبِيبٌ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُطَوِّسِ ‏ ‏فَلَقِيتُ ‏ ‏ابْنَ الْمُطَوِّسِ ‏ ‏فَحَدَّثَنِي عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَفْطَرَ يَوْمًا مِنْ رَمَضَانَ مِنْ غَيْرِ رُخْصَةٍ رَخَّصَهَا اللَّهُ عَزَّ وَجَلَّ لَمْ يَقْضِ عَنْهُ صِيَامُ الدَّهْرِ وَإِنْ صَامَهُ ‏","","",""],[9701,9701,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ الْمُطَوِّسِ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَفْطَرَ يَوْمًا فِي رَمَضَانَ مِنْ غَيْرِ مَرَضٍ وَلَا رُخْصَةٍ لَمْ يَقْضِ عَنْهُ صِيَامُ الدَّهْرِ كُلِّهِ وَإِنْ صَامَهُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏حَبِيبٌ ‏ ‏حَدَّثَنِي ‏ ‏عُمَارَةُ ‏ ‏عَنِ ‏ ‏أَبِي الْمُطَوِّسِ ‏ ‏فَلَقِيتُ ‏ ‏أَبَا الْمُطَوِّسِ ‏ ‏فَحَدَّثَنِي ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏فَقَالَ ‏ ‏أَبُو الْمُطَوِّسِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُطَوِّسِ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏فَذَكَرَهُ ‏","","",""],[9702,9702,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏أَشْعَثَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَلَسَ بَيْنَ ‏ ‏شُعَبِهَا ‏ ‏الْأَرْبَعِ وَاجْتَهَدَ فَقَدْ وَجَبَ الْغُسْلُ ‏","","",""],[9703,9703,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ أَطْفَالِ الْمُشْرِكِينَ فَقَالَ ‏ ‏اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ‏","","",""],[9704,9704,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَانْخَنَسْتُ فَذَهَبْتُ فَاغْتَسَلْتُ ثُمَّ جِئْتُ فَقَالَ أَيْنَ كُنْتَ قَالَ كُنْتَ لَقِيتَنِي وَأَنَا جُنُبٌ فَكَرِهْتُ أَنْ أُجَالِسَكَ عَلَى غَيْرِ طَهَارَةٍ فَقَالَ ‏ ‏إِنَّ الْمُسْلِمَ لَا يَنْجُسُ ‏","","",""],[9705,9705,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَثَّ عَلَى ‏ ‏الصَّدَقَةِ ‏ ‏فَقَالَ رَجُلٌ عِنْدِي دِينَارٌ قَالَ ‏ ‏تَصَدَّقْ بِهِ عَلَى نَفْسِكَ قَالَ عِنْدِي دِينَارٌ آخَرُ قَالَ تَصَدَّقْ بِهِ عَلَى زَوْجَتِكَ قَالَ عِنْدِي دِينَارٌ آخَرُ قَالَ تَصَدَّقْ بِهِ عَلَى وَلَدِكَ قَالَ عِنْدِي دِينَارٌ آخَرُ قَالَ تَصَدَّقْ بِهِ عَلَى خَادِمِكَ قَالَ عِنْدِي دِينَارٌ آخَرُ قَالَ أَنْتَ أَبْصَرُ ‏","","",""],[9706,9706,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَوْ ‏ ‏عَنِ ‏ ‏أَبِي سَعِيدٍ ‏ ‏شَكَّ ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ ‏ ‏يُقَالُ لِصَاحِبِ الْقُرْآنِ يَوْمَ الْقِيَامَةِ ‏ ‏اقْرَهْ ‏ ‏وَارْقَهْ فَإِنَّ مَنْزِلَتَكَ عِنْدَ آخِرِ آيَةٍ تَقْرَؤُهَا ‏","","",""],[9707,9707,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏وَإِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبَّادٌ ‏ ‏الْمَعْنَى ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَقَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقْبَلُ ‏ ‏الصَّدَقَاتِ ‏ ‏وَيَأْخُذُهَا بِيَمِينِهِ ‏ ‏فَيُرَبِّيهَا لِأَحَدِكُمْ كَمَا يُرَبِّي أَحَدُكُمْ مُهْرَهُ ‏ ‏أَوْ ‏ ‏فَلُوَّهُ ‏ ‏أَوْ ‏ ‏فَصِيلَهُ ‏ ‏حَتَّى إِنَّ اللُّقْمَةَ لَتَصِيرُ مِثْلَ ‏ ‏أُحُدٍ ‏ ‏وَقَالَ ‏ ‏وَكِيعٌ ‏ ‏فِي حَدِيثِهِ وَتَصْدِيقُ ذَلِكَ فِي كِتَابِ اللَّهِ ‏ { ‏وَهُوَ الَّذِي يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ ‏} { ‏وَيَأْخُذُ ‏ ‏الصَّدَقَاتِ ‏ } ‏وَ ‏ { ‏يَمْحَقُ اللَّهُ الرِّبَا ‏ ‏وَيُرْبِي ‏ ‏الصَّدَقَاتِ ‏ }","","",""],[9708,9708,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ أَطَاعَ الْإِمَامَ فَقَدْ أَطَاعَنِي وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ وَمَنْ عَصَى الْإِمَامَ فَقَدْ عَصَى اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[9709,9709,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَتْ لَهُ امْرَأَتَانِ يَمِيلُ مَعَ إِحْدَاهُمَا عَلَى الْأُخْرَى جَاءَ يَوْمَ الْقِيَامَةِ وَأَحَدُ ‏ ‏شِقَّيْهِ ‏ ‏سَاقِطٌ ‏","","",""],[9710,9710,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏وَأَبِي رَزِينٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَفَعَهُ ‏ ‏كَذَا قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ مَنَامِهِ فَلَا ‏ ‏يَغْمِسْ ‏ ‏يَدَهُ فِي الْإِنَاءِ حَتَّى يَغْسِلَهَا ثَلَاثًا فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏","","",""],[9711,9711,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ رَأَى قَوْمًا يَتَوَضَّئُونَ مِنْ الْمَطْهَرَةِ فَقَالَ أَسْبِغُوا الْوُضُوءَ فَإِنِّي سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْعَرَاقِيبِ ‏ ‏مِنْ النَّارِ ‏","","",""],[9712,9712,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا وُضُوءَ إِلَّا مِنْ صَوْتٍ أَوْ رِيحٍ ‏","","",""],[9713,9713,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ الْأَوْدِيُّ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُومَنَّ أَحَدُكُمْ إِلَى الصَّلَاةِ وَبِهِ ‏ ‏أَذًى ‏ ‏مِنْ ‏ ‏غَائِطٍ ‏ ‏أَوْ بَوْلٍ ‏","","",""],[9714,9714,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنِ ‏ ‏أَبِي الشَّعْثَاءِ ‏ ‏قَالَ ‏ ‏خَرَجَ رَجُلٌ مِنْ الْمَسْجِدِ بَعْدَ مَا أُذِّنَ فِيهِ بِالْعَصْرِ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَمَّا هَذَا فَقَدْ عَصَى ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9715,9715,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَوْدُودٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي حَدْرَدٍ الْأَسْلَمِيِّ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَزَقَ أَحَدُكُمْ ‏ ‏فِي ‏ ‏مَسْجِدِي ‏ ‏أَوْ الْمَسْجِدِ ‏ ‏فَلْيَحْفِرْ وَلْيُعَمِّقْ أَوْ لِيَبْزُقْ فِي ثَوْبِهِ حَتَّى يُخْرِجَهُ ‏","","",""],[9716,9716,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏صَلَّى صَلَاةً ‏ ‏تَجَوَّزَ ‏ ‏فِيهَا فَقُلْتُ لَهُ هَكَذَا كَانَ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ وَأَوْجَزَ ‏","","",""],[9717,9717,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ اللَّهُمَّ أَرْشِدْ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ ‏","","",""],[9718,9718,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَجَوَّزُوا ‏ ‏فِي الصَّلَاةِ فَإِنَّ فِيهِمْ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ ‏","","",""],[9719,9719,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَثْقَلَ الصَّلَاةِ عَلَى الْمُنَافِقِينَ صَلَاةُ الْعِشَاءِ وَالْفَجْرِ وَلَوْ يَعْلَمُونَ مَا فِيهِمَا لَأَتَوْهُمَا وَلَوْ حَبْوًا ‏","","",""],[9720,9720,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ‏ ‏هَمَمْتُ أَنْ آمُرَ فِتْيَتِي فَيَجْمَعُوا حُزَمَ الْحَطَبِ ثُمَّ آمُرَ بِالصَّلَاةِ فَتُقَامَ ثُمَّ أُحَرِّقَ عَلَى قَوْمٍ لَا يَشْهَدُونَ الصَّلَاةَ ‏","","",""],[9721,9721,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقْرَأُ فِي الْفَجْرِ يَوْمَ الْجُمُعَةِ ‏ ‏الم تَنْزِيلُ ‏ ‏وَهَلْ أَتَى عَلَى الْإِنْسَانِ ‏","","",""],[9722,9722,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَيْتُمْ الصَّلَاةَ فَأْتُوهَا بِالْوَقَارِ ‏ ‏وَالسَّكِينَةِ ‏ ‏فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا ‏","","",""],[9723,9723,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا يَخَافُ الَّذِي يَرْفَعُ رَأْسَهُ قَبْلَ الْإِمَامِ أَنْ يُحَوَّلَ رَأْسُهُ رَأْسَ حِمَارٍ ‏","","",""],[9724,9724,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُمَيْرٍ ‏ ‏عَنْ ‏ ‏مَوْلًى لِقُرَيْشٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُصَلِّيَ الرَّجُلُ حَتَّى يَحْتَزِمَ قَالَ وَسَمِعْتُهُ يُحَدِّثُهُ قَالَ نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الْمَغَانِمِ حَتَّى تُقْسَمَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَالَ مَرَّةً وَيُعْلَمَ مَا بَقِيَ مَا هِيَ ‏ ‏قَالَ وَنَهَى عَنْ بَيْعِ الثِّمَارِ حَتَّى ‏ ‏تُحْرَزَ ‏ ‏مِنْ كُلِّ ‏ ‏عَارِضٍ ‏","","",""],[9725,9725,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا وَخِيَارُكُمْ خِيَارُكُمْ لِنِسَائِكُمْ ‏","","",""],[9726,9726,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَعْتَقَ ‏ ‏شِقْصًا ‏ ‏لَهُ فِي مَمْلُوكٍ فَعَلَيْهِ ‏ ‏خَلَاصُهُ ‏ ‏كُلِّهِ فِي مَالِهِ فَإِنْ لَمْ يَكُنْ لَهُ مَالٌ ‏ ‏اسْتُسْعِيَ ‏ ‏الْعَبْدُ غَيْرَ مَشْقُوقٍ عَلَيْهِ ‏","","",""],[9727,9727,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَالِحٌ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ ‏","","",""],[9728,9728,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي إِنَّ الشَّيْطَانَ لَا يَتَشَبَّهُ بِي ‏","","",""],[9729,9729,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَامِرٌ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظَّهْرُ ‏ ‏يُرْكَبُ بِنَفَقَةٍ إِذَا كَانَ مَرْهُونًا وَيُشْرَبُ لَبَنُ ‏ ‏الدَّرِّ ‏ ‏إِذَا كَانَ مَرْهُونًا وَعَلَى الَّذِي يَشْرَبُ وَيَرْكَبُ نَفَقَتُهُ ‏","","",""],[9730,9730,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عِمْرَانَ أَبِي بَكْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَوْصَانِي ‏ ‏خَلِيلِي ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَلَاثٍ ‏ ‏الْوَتْرِ ‏ ‏قَبْلَ النَّوْمِ وَصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَالْغُسْلِ يَوْمَ الْجُمُعَةِ ‏","","",""],[9731,9731,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنِ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏إِنْ شَاءَ اللَّهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلْمَانُ الْأَغَرُّ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[9732,9732,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٌ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَالْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏التَّسْبِيحُ لِلرِّجَالِ وَالتَّصْفِيقُ لِلنِّسَاءِ ‏","","",""],[9733,9733,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏أَمْسَكَ ‏ ‏كَلْبًا نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطٌ ‏ ‏إِلَّا كَلْبَ ‏ ‏حَرْثٍ ‏ ‏أَوْ مَاشِيَةٍ ‏","","",""],[9734,9734,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْمُبَارَكِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ضَمْضَمٌ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلِ ‏ ‏الْأَسْوَدَيْنِ ‏ ‏فِي الصَّلَاةِ الْحَيَّةِ وَالْعَقْرَبِ ‏","","",""],[9735,9735,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ رَمَضَانَ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏فَذَكَرَا مِثْلَهُ إِلَّا أَنَّهُمَا قَالَا مَنْ قَامَ رَمَضَانَ إِيمَانًا ‏","","",""],[9736,9736,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مُزَاحِمِ بْنِ زُفَرَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا أَعْلَمُ شَكَّ ‏ ‏يَحْيَى ‏ ‏قَالَ ‏ ‏دِينَارٌ أَنْفَقْتَهُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ وَدِينَارٌ فِي الْمَسَاكِينِ وَدِينَارٌ فِي رَقَبَةٍ وَدِينَارٌ فِي أَهْلِكَ أَعْظَمُهَا أَجْرًا الدِّينَارُ الَّذِي تُنْفِقُهُ عَلَى أَهْلِكَ ‏","","",""],[9737,9737,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ يَمُوتُ لَهُ ثَلَاثَةٌ مِنْ الْوَلَدِ لَمْ يَبْلُغُوا ‏ ‏الْحِنْثَ ‏ ‏فَتَمَسُّهُ النَّارُ إِلَّا ‏ ‏تَحِلَّةَ ‏ ‏الْقَسَمِ ‏","","",""],[9738,9738,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَضْلُ صَلَاةِ الْجَمَاعَةِ عَلَى صَلَاةِ الرَّجُلِ وَحْدَهُ خَمْسَةٌ وَعِشْرُونَ جُزْءًا ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏إِنْ شَاءَ اللَّهُ ‏","","",""],[9739,9739,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زِيَادٌ ‏ ‏يَعْنِي مَوْلَى ‏ ‏بَنِي مَخْزُومٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَحْنُ ‏ ‏الْآخِرُونَ ‏ ‏السَّابِقُونَ يَوْمَ الْقِيَامَةِ فَأَوَّلُ ‏ ‏زُمْرَةٍ ‏ ‏مِنْ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ صُورَةُ كُلِّ رَجُلٍ مِنْهُمْ عَلَى صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ ثُمَّ الَّذِينَ يَلُونَهُمْ كَأَشَدِّ ضَوْءِ نَجْمٍ فِي السَّمَاءِ ثُمَّ هُمْ مَنَازِلُ بَعْدَ ذَلِكَ ‏","","",""],[9740,9740,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زِيَادٌ ‏ ‏مَوْلَى ‏ ‏بَنِي مَخْزُومٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْكُمْ أَحَدٌ دَاخِلٌ الْجَنَّةَ بِعَمَلِهِ قِيلَ وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ بِرَحْمَةٍ مِنْهُ وَفَضْلٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[9741,9741,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَاءَ خَادِمُ أَحَدِكُمْ بِطَعَامِهِ فَلْيُجْلِسْهُ مَعَهُ فَإِنْ لَمْ يُجْلِسْهُ فَلْيُنَاوِلْهُ مِنْهُ ‏","","",""],[9742,9742,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ذَكْوَانُ أَبُو صَالِحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي مَا تَخَلَّفْتُ عَنْ ‏ ‏سَرِيَّةٍ ‏ ‏تَخْرُجُ وَلَكِنْ لَا يَجِدُونَ ‏ ‏حَمُولَةً ‏ ‏وَلَا أَجِدُ مَا أَحْمِلُهُمْ وَيَشُقُّ عَلَيْهِمْ أَنْ يَتَخَلَّفُوا عَنِّي وَلَوَدِدْتُ أَنِّي قَاتَلْتُ فِي سَبِيلِ اللَّهِ فَقُتِلْتُ ثُمَّ أُحْيِيتُ ثُمَّ قُتِلْتُ ثُمَّ أُحْيِيتُ ثُمَّ قُتِلْتُ ثُمَّ أُحْيِيتُ ‏","","",""],[9743,9743,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَجْلَانُ ‏ ‏مَوْلَى ‏ ‏الْمُشْمَعِلِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ رُكُوبِ ‏ ‏الْبَدَنَةِ ‏ ‏فَقَالَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا وَيْلَكَ ‏","","",""],[9744,9744,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ الرَّجُلُ لِصَاحِبِهِ يَوْمَ الْجُمُعَةِ وَالْإِمَامُ يَخْطُبُ أَنْصِتْ فَقَدْ ‏ ‏لَغَا ‏","","",""],[9745,9745,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ الْأَعْرَجُ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ ‏ ‏سَجْدَةً ‏ ‏مِنْ صَلَاةِ الصُّبْحِ قَبْلَ طُلُوعِ الشَّمْسِ فَقَدْ أَدْرَكَ وَمَنْ أَدْرَكَ ‏ ‏سَجْدَةً ‏ ‏مِنْ صَلَاةِ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَ ‏","","",""],[9746,9746,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِّثُوا عَنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَلَا حَرَجَ ‏","","",""],[9747,9747,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنِ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ وَجَدَ مَالَهُ بِعَيْنِهِ عِنْدَ رَجُلٍ قَدْ أَفْلَسَ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[9748,9748,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمٌ يَصُومُهُ أَحَدُكُمْ فَلَا ‏ ‏يَرْفُثْ ‏ ‏وَلَا يَجْهَلْ فَإِنْ جُهِلَ عَلَيْهِ فَلْيَقُلْ إِنِّي امْرُؤٌ صَائِمٌ ‏","","",""],[9749,9749,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏وَقُرْآنَ الْفَجْرِ إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا ‏} ‏قَالَ ‏ ‏تَشْهَدُ مَلَائِكَةُ اللَّيْلِ وَمَلَائِكَةُ النَّهَارِ ‏","","",""],[9750,9750,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاكُمْ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏هُمْ أَرَقُّ أَفْئِدَةً الْإِيمَانُ يَمَانٍ وَالْفِقْهُ يَمَانٍ وَالْحِكْمَةُ يَمَانِيَةٌ ‏","","",""],[9751,9751,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْمُثَنَّى ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ كَعْبٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَشَاجَرْتُمْ ‏ ‏أَوْ اخْتَلَفْتُمْ ‏ ‏فِي الطَّرِيقِ فَدَعُوا سَبْعَ أَذْرُعٍ ‏","","",""],[9752,9752,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏زُرَارَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ تَجَاوَزَ لِأُمَّتِي عَمَّا حَدَّثَتْ بِهِ أَنْفُسَهَا مَا لَمْ تَعْمَلْ بِهِ ‏ ‏أَوْ تَكَلَّمْ ‏","","",""],[9753,9753,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏الْمَعْنَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِذَا مُتُّ فَلَا تَضْرِبُوا عَلَيَّ ‏ ‏فُسْطَاطًا ‏ ‏وَلَا تَتْبَعُونِي بِنَارٍ وَأَسْرِعُوا بِي إِلَى رَبِّي فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا وُضِعَ الْعَبْدُ ‏ ‏أَوْ الرَّجُلُ ‏ ‏الصَّالِحُ عَلَى سَرِيرِهِ قَالَ قَدِّمُونِي قَدِّمُونِي وَإِذَا وُضِعَ الرَّجُلُ السَّوْءُ قَالَ وَيْلَكُمْ أَيْنَ تَذْهَبُونَ بِي ‏","","",""],[9754,9754,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ أَبِي نَافِعٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏سَبَقَ ‏ ‏إِلَّا فِي ‏ ‏خُفٍّ ‏ ‏أَوْ ‏ ‏نَصْلٍ ‏ ‏أَوْ ‏ ‏حَافِرٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَيَزِيدُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ أَبِي نَافِعٍ ‏ ‏مَوْلَى ‏ ‏أَبِي أَحْمَدَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[9755,9755,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُنْكَحُ الْمَرْأَةُ عَلَى عَمَّتِهَا وَلَا عَلَى خَالَتِهَا ‏","","",""],[9756,9756,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو كَثِيرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَمْرُ فِي هَاتَيْنِ الشَّجَرَتَيْنِ النَّخْلَةِ وَالْعِنَبَةِ ‏","","",""],[9757,9757,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ ‏ ‏عَنِ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَا عَابَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامًا قَطُّ كَانَ ‏ ‏إِذَا اشْتَهَاهُ أَكَلَهُ وَإِذَا لَمْ يَشْتَهِهِ تَرَكَهُ ‏","","",""],[9758,9758,"","","‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ كَيْسَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏فَإِنْ اتَّبَعَهَا حَتَّى ‏ ‏تُوضَعَ ‏ ‏فِي الْقَبْرِ فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏مَا ‏ ‏الْقِيرَاطُ ‏ ‏قَالَ ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[9759,9759,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِرَاءٌ فِي الْقُرْآنِ كُفْرٌ ‏","","",""],[9760,9760,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَمْنَعُوا ‏ ‏إِمَاءَ ‏ ‏اللَّهِ مَسَاجِدَ اللَّهِ وَلْيَخْرُجْنَ ‏ ‏تَفِلَاتٍ ‏","","",""],[9761,9761,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏لِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ حِينَ يُفْطِرُ وَفَرْحَةٌ حِينَ يَلْقَى رَبَّهُ وَلَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[9762,9762,"","","‏ ‏وَبِإِسْنَادِهِ هَذَا ‏ ‏قَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُسْتَأْمَرُ ‏ ‏الْيَتِيمَةُ فِي نَفْسِهَا فَإِنْ سَكَتَتْ فَهُوَ إِذْنُهَا وَإِنْ أَبَتْ فَلَا جَوَازَ عَلَيْهَا ‏","","",""],[9763,9763,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَرْحُ ‏ ‏الْعَجْمَاءِ ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏","","",""],[9764,9764,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ بَيْعَتَيْنِ فِي بَيْعَةٍ وَعَنْ لِبْسَتَيْنِ أَنْ ‏ ‏يَشْتَمِلَ ‏ ‏أَحَدُكُمْ ‏ ‏الصَّمَّاءَ ‏ ‏فِي ثَوْبٍ وَاحِدٍ وَيَحْتَبِيَ بِثَوْبٍ وَاحِدٍ لَيْسَ بَيْنَهُ وَبَيْنَ السَّمَاءِ شَيْءٌ ‏","","",""],[9765,9765,"","","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَبَّرَ الْإِمَامُ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا سَجَدَ فَاسْجُدُوا وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا ‏","","",""],[9766,9766,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَيْسُ بْنُ أَبِي حَازِمٍ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏نُسَلِّمُ عَلَيْهِ قَالَ قُلْنَا حَدِّثْنَا فَقَالَ صَحِبْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَ سِنِينَ مَا كُنْتُ سَنَوَاتٍ قَطُّ ‏ ‏أَعْقَلَ ‏ ‏مِنِّي فِيهِنَّ وَلَا أَحَبَّ إِلَيَّ أَنْ ‏ ‏أَعِيَ ‏ ‏مَا يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِنَّ وَإِنِّي رَأَيْتُهُ يَقُولُ بِيَدِهِ ‏ ‏قَرِيبٌ بَيْنَ يَدَيْ السَّاعَةِ تُقَاتِلُونَ قَوْمًا نِعَالُهُمْ الشَّعْرُ وَتُقَاتِلُونَ قَوْمًا صِغَارَ الْأَعْيُنِ حُمْرَ الْوُجُوهِ كَأَنَّهَا ‏ ‏الْمَجَانُّ ‏ ‏الْمُطْرَقَةُ وَاللَّهِ لَأَنْ ‏ ‏يَغْدُوَ ‏ ‏أَحَدُكُمْ فَيَحْتَطِبَ عَلَى ظَهْرِهِ فَيَبِيعَهُ وَيَسْتَغْنِيَ بِهِ وَيَتَصَدَّقَ مِنْهُ خَيْرٌ لَهُ مِنْ أَنْ يَأْتِيَ رَجُلًا فَيَسْأَلَهُ ‏ ‏يُؤْتِيهِ أَوْ يَمْنَعُهُ وَذَلِكَ أَنَّ الْيَدَ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏ ‏وَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏","","",""],[9767,9767,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏","","",""],[9768,9768,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏وَإِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏ضَمْضَمِ بْنِ جَوْسٍ الْهِفَّانِيِّ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ الْأَسْوَدَيْنِ فِي الصَّلَاةِ الْعَقْرَبِ وَالْحَيَّةِ ‏","","",""],[9769,9769,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَفْلَحُ بْنُ حُمَيْدٍ ‏ ‏عَنِ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ الرَّجُلِ فِي جَمَاعَةٍ تَزِيدُ عَلَى صَلَاةِ ‏ ‏الْفَذِّ ‏ ‏خَمْسًا وَعِشْرِينَ دَرَجَةً ‏","","",""],[9770,9770,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفْسُ الْمُؤْمِنِ مُعَلَّقَةٌ مَا كَانَ عَلَيْهِ دَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ فِيهِ عَنْ أَبِيهِ ‏ ‏مِثْلَهُ ‏","","",""],[9771,9771,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوا لَا إِلَهَ إِلَّا اللَّهُ ‏ ‏عَصَمُوا ‏ ‏مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا ‏ ‏بِحَقِّهَا ‏ ‏وَحِسَابُهُمْ عَلَى اللَّهِ عَزَّ وَجَلَّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ ‏ ‏أُقَاتِلَ النَّاسَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[9772,9772,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلْمِ بْنِ عَبْدِ الرَّحْمَنِ النَّخَعِيِّ ‏ ‏عَنِ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَكْرَهُ ‏ ‏الشِّكَالَ ‏ ‏مِنْ الْخَيْلِ ‏","","",""],[9773,9773,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْمَلَائِكَةَ لَا تَصْحَبُ رُفْقَةً فِيهَا جَرَسٌ وَلَا كَلْبٌ ‏","","",""],[9774,9774,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ سَتَحْرِصُونَ عَلَى ‏ ‏الْإِمَارَةِ ‏ ‏وَسَتَصِيرُ حَسْرَةً وَنَدَامَةً ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏يَوْمَ الْقِيَامَةِ ‏ ‏نِعْمَتِ الْمُرْضِعَةُ وَبِئْسَتِ الْفَاطِمَةُ ‏","","",""],[9775,9775,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَمُّوا الْعِنَبَ الْكَرْمَ فَإِنَّمَا الْكَرْمُ الرَّجُلُ الْمُسْلِمُ ‏","","",""],[9776,9776,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ إِسْمَاعِيلَ الْمَخْزُومِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبَّادٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ مُشْرِكُو ‏ ‏قُرَيْشٍ ‏ ‏يُخَاصِمُونَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْقَدَرِ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏يَوْمَ يُسْحَبُونَ فِي النَّارِ عَلَى وُجُوهِهِمْ ذُوقُوا مَسَّ ‏ ‏سَقَرَ ‏ ‏إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ ‏}","","",""],[9777,9777,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ يَعْنِي اللَّيْثِيَّ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏سَمِعَهُ عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرِيدُ سَفَرًا فَقَالَ يَا رَسُولَ اللَّهِ أَوْصِنِي فَقَالَ ‏ ‏أُوصِيكَ بِتَقْوَى اللَّهِ وَالتَّكْبِيرِ عَلَى كُلِّ ‏ ‏شَرَفٍ ‏ ‏فَلَمَّا مَضَى قَالَ اللَّهُمَّ ‏ ‏ازْوِ ‏ ‏لَهُ الْأَرْضَ وَهَوِّنْ عَلَيْهِ السَّفَرَ ‏","","",""],[9778,9778,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏زِيَادٍ ‏ ‏مَوْلَى ‏ ‏بَنِي مَخْزُومٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏كِسْرَى ‏ ‏بَعْدَ ‏ ‏كِسْرَى ‏ ‏وَلَا ‏ ‏قَيْصَرَ ‏ ‏بَعْدَ ‏ ‏قَيْصَرَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ لَتُنْفَقَنَّ كُنُوزُهُمَا فِي سَبِيلِ اللَّهِ ‏","","",""],[9779,9779,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَكِيمٍ الْأَثْرَمِ ‏ ‏عَنِ ‏ ‏أَبِي تَمِيمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏أَتَى ‏ ‏حَائِضًا ‏ ‏أَوْ امْرَأَةً ‏ ‏فِي ‏ ‏دُبُرِهَا ‏ ‏أَوْ كَاهِنًا فَصَدَّقَهُ بِمَا يَقُولُ فَقَدْ كَفَرَ بِمَا أَنْزَلَ اللَّهُ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9780,9780,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عُثْمَانَ ‏ ‏عَنِ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَصُومُ الْمَرْأَةُ يَوْمًا وَاحِدًا وَزَوْجُهَا شَاهِدٌ إِلَّا بِإِذْنِهِ إِلَّا رَمَضَانَ ‏","","",""],[9781,9781,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْمُنَابَذَةِ ‏ ‏وَالْمُلَامَسَةِ ‏","","",""],[9782,9782,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنِ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خِيَارُكُمْ أَحْسَنُكُمْ ‏ ‏قَضَاءً ‏","","",""],[9783,9783,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْفَضْلِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي تَلْبِيَتِهِ ‏ ‏لَبَّيْكَ إِلَهَ الْحَقِّ ‏","","",""],[9784,9784,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ ‏ ‏الصَّدَقَةِ ‏ ‏مَا كَانَ عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏","","",""],[9785,9785,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏أَخَذَ تَمْرَةً مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏فَلَاكَهَا ‏ ‏فِي ‏ ‏فِيهِ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِخْ كِخْ ثَلَاثًا إِنَّا ‏ ‏لَا تَحِلُّ لَنَا ‏ ‏الصَّدَقَةُ ‏","","",""],[9786,9786,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُزَاحِمِ بْنِ زُفَرَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دِينَارًا أَنْفَقْتَهُ فِي سَبِيلِ اللَّهِ وَدِينَارًا أَنْفَقْتَهُ فِي رَقَبَةٍ وَدِينَارًا تَصَدَّقْتَ بِهِ وَدِينَارًا أَنْفَقْتَهُ عَلَى أَهْلِكَ ‏ ‏أَفْضَلُهَا الدِّينَارُ الَّذِي أَنْفَقْتَهُ عَلَى أَهْلِكَ ‏","","",""],[9787,9787,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ عَمَلِ ابْنِ ‏ ‏آدَمَ ‏ ‏يُضَاعَفُ الْحَسَنَةُ عَشَرَةُ أَمْثَالِهَا إِلَى سَبْعِ مِائَةِ ضِعْفٍ إِلَى مَا شَاءَ اللَّهُ يَقُولُ اللَّهُ عَزَّ وَجَلَّ إِلَّا الصَّوْمَ فَإِنَّهُ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ يَدَعُ طَعَامَهُ وَشَرَابَهُ مِنْ أَجْلِي وَلِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ حِينَ يُفْطِرُ وَفَرْحَةٌ عِنْدَ لِقَاءِ رَبِّهِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ عَزَّ وَجَلَّ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏ ‏الصَّوْمُ ‏ ‏جُنَّةٌ ‏ ‏الصَّوْمُ جُنَّةٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو صَالِحٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[9788,9788,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَا تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا أَوَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ ‏ ‏أَفْشُوا ‏ ‏السَّلَامَ بَيْنَكُمْ ‏","","",""],[9789,9789,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَلِيحٍ الْمَدَنِيُّ ‏ ‏شَيْخٌ مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا صَالِحٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَدْعُ اللَّهَ غَضِبَ اللَّهُ عَلَيْهِ ‏","","",""],[9790,9790,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏فَرَجُ بْنُ فَضَالَةَ ‏ ‏عَنِ ‏ ‏أَبِي سَعْدٍ الْحِمْصِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏دُعَاءٌ حَفِظْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَدَعُهُ ‏ ‏اللَّهُمَّ اجْعَلْنِي أُعْظِمُ شُكْرَكَ وَأَتَّبِعُ نَصِيحَتَكَ وَأُكْثِرُ ذِكْرَكَ وَأَحْفَظُ وَصِيَّتَكَ ‏","","",""],[9791,9791,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي عَائِشَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَشَهَّدَ أَحَدُكُمْ فَلْيَسْتَعِذْ بِاللَّهِ مِنْ أَرْبَعٍ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَعَذَابِ الْقَبْرِ وَشَرِّ ‏ ‏فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏وَمِنْ ‏ ‏فِتْنَةِ ‏ ‏الْمَحْيَا وَالْمَمَاتِ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنِ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[9792,9792,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا ‏","","",""],[9793,9793,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدَانُ الْجُهَنِيُّ ‏ ‏عَنْ ‏ ‏سَعْدٍ أَبِي مُجَاهِدٍ الطَّائِيِّ ‏ ‏عَنِ ‏ ‏أَبِي مُدِلَّةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّائِمُ لَا تُرَدُّ دَعْوَتُهُ ‏","","",""],[9794,9794,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنِ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَقَدَّمُوا ‏ ‏شَهْرَ رَمَضَانَ بِصِيَامِ يَوْمٍ أَوْ يَوْمَيْنِ إِلَّا رَجُلًا كَانَ يَصُومُ صَوْمًا فَلْيَصُمْهُ ‏","","",""],[9795,9795,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَحَّرُوا فَإِنَّ فِي السُّحُورِ بَرَكَةً ‏","","",""],[9796,9796,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ عَلَى الرَّجُلِ الْمُسْلِمِ فِي عَبْدِهِ وَلَا خَادِمِهِ وَلَا فَرَسِهِ ‏ ‏صَدَقَةٌ ‏","","",""],[9797,9797,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَشُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ عَلَى الْمُسْلِمِ فِي فَرَسِهِ وَلَا عَبْدِهِ ‏ ‏صَدَقَةٌ ‏","","",""],[9798,9798,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏وَأَبِي رَزِينٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَرْفَعُهُ قَالَ ‏ ‏إِذَا انْقَطَعَ ‏ ‏شِسْعُ ‏ ‏أَحَدِكُمْ فَلَا يَمْشِ فِي النَّعْلِ الْوَاحِدَةِ ‏","","",""],[9799,9799,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا انْتَعَلَ أَحَدُكُمْ فَلْيَبْدَأْ بِالْيُمْنَى وَإِذَا خَلَعَ فَلْيَبْدَأْ بِالْيُسْرَى لِيَنْعَلْهُمَا جَمِيعًا أَوْ ‏ ‏لِيُحْفِهِمَا ‏ ‏جَمِيعًا ‏","","",""],[9800,9800,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُبْسِ ‏ ‏الصَّمَّاءِ ‏ ‏وَأَنْ ‏ ‏يَحْتَبِيَ ‏ ‏الرَّجُلُ فِي الثَّوْبِ الْوَاحِدِ ‏ ‏يُفْضِي ‏ ‏بِفَرْجِهِ إِلَى السَّمَاءِ ‏","","",""]];
